SELECT n.id, n.source, n.profile, n.fetch_id, n.publication_id, n.published_at, n.published_offset, n.published_has_time, n.dispatched_at, n.dispatched_offset, n.dispatched_has_time, n.parse_state, v.tender_id, v.seq, v.published_at AS v_published_at, (SELECT count(*) FROM tender_versions x WHERE x.tender_id = v.tender_id) AS n_versions FROM notices n LEFT JOIN tender_versions v ON v.caused_by_notice_id = n.id WHERE n.id = 26044864
UNION ALL
